def upperEnvelope (n d : ℕ) (q : ℝ) : ℝ≥0∞ :=
  if 0 < q then ENNReal.ofReal
    (5 * ((d : ℝ) + 1) ^ 2 / n + 4 * d * (1 - q) / (n * q)) else ⊤

